INSERT INTO `creature_text` (`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES
(3391, 100, 0, 'Ah, so Risa is now the one who throw out these parties nowadays, eh? That\'s very nice to know, thank for that, my friend! Knowledge is power and power can bring you a lot of gold, right? Exactly. I\'ll see you around, partner.', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66115'),
(81006, 0, 0, 'The shark looks scared to death and eager to get out of this horrific place full of people like you.', 16, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66840'),
(60752, 0, 0, 'O, de powerful Loa! Smite ya enemies!', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66451'),
(60752, 1, 0, 'Da ogres of Dunemaul. Curse them!', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66452'),
(60752, 2, 0, 'Let dem feel your fury...', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66453'),
(60750, 0, 0, 'Viceclaw my dear. Da feast today!', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66454'),
(60750, 1, 0, 'Good boy.', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66455'),
(60755, 0, 0, 'Viceclaw: <cackles>', 16, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66750');
