INSERT INTO `npc_text` (`ID`, `text0_0`, `text0_1`, `Probability0`, `VerifiedBuild`) VALUES (9030030, 'The Horde welcomes anyone who does not fit anywhere else. Thrall welcomed the Darkspear in spite of Troll history with the Second Horde. I cannot leave them, my kind, in the desert.\n\nI be not saying they join the Horde yet, but we will help. And stop the madness in Zul\'Farrak.', 'The Horde welcomes anyone who does not fit anywhere else. Thrall welcomed the Darkspear in spite of Troll history with the Second Horde. I cannot leave them, my kind, in the desert.\n\nI be not saying they join the Horde yet, but we will help. And stop the madness in Zul\'Farrak.', 1, 0);
INSERT INTO `gossip_menu` (`MenuID`, `TextID`) VALUES (9030030, 9030030);
INSERT INTO `npc_text` (`ID`, `text0_0`, `text0_1`, `Probability0`, `VerifiedBuild`) VALUES (9030029, 'I see it too. Yet I have trouble believing their intents. Among the few Troll tribes left in Kalimdor, the Sandfury had a terrible reputation, even before Ukorz took over.', 'I see it too. Yet I have trouble believing their intents. Among the few Troll tribes left in Kalimdor, the Sandfury had a terrible reputation, even before Ukorz took over.', 1, 0);
INSERT INTO `gossip_menu` (`MenuID`, `TextID`) VALUES (9030029, 9030029);
INSERT INTO `gossip_menu_option` (`MenuID`, `OptionID`, `OptionIcon`, `OptionText`, `OptionBroadcastTextID`, `OptionType`, `OptionNpcFlag`, `ActionMenuID`, `ActionPoiID`, `BoxCoded`, `BoxMoney`, `BoxText`, `BoxBroadcastTextID`, `VerifiedBuild`) VALUES (9030029, 0, 0, 'I don\'t know them well, but they welcomed me in their village like a friend. They had to leave Zul\'Farrak because of persecution and despotism of their leader. They ran away, because they saw what is happening there. They saw the darkness, the corruption.', 0, 1, 1, 0, 0, 0, 0, NULL, 0, 0);
INSERT INTO `npc_text` (`ID`, `text0_0`, `text0_1`, `Probability0`, `VerifiedBuild`) VALUES (9030028, 'We, Darkspear, had to flee our homeland twice. Once, when the Gurubashi drove us from Stranglethorn, and then the naga drove us away from the Isles. We know the feeling of loss.', 'We, Darkspear, had to flee our homeland twice. Once, when the Gurubashi drove us from Stranglethorn, and then the naga drove us away from the Isles. We know the feeling of loss.', 1, 0);
INSERT INTO `gossip_menu` (`MenuID`, `TextID`) VALUES (9030028, 9030028);
INSERT INTO `gossip_menu_option` (`MenuID`, `OptionID`, `OptionIcon`, `OptionText`, `OptionBroadcastTextID`, `OptionType`, `OptionNpcFlag`, `ActionMenuID`, `ActionPoiID`, `BoxCoded`, `BoxMoney`, `BoxText`, `BoxBroadcastTextID`, `VerifiedBuild`) VALUES (9030028, 0, 0, 'The Sandfury in Sandmoon Village remind me of the Darkspear.', 0, 1, 1, 9030029, 0, 0, 0, NULL, 0, 0);
INSERT INTO `gossip_menu_option` (`MenuID`, `OptionID`, `OptionIcon`, `OptionText`, `OptionBroadcastTextID`, `OptionType`, `OptionNpcFlag`, `ActionMenuID`, `ActionPoiID`, `BoxCoded`, `BoxMoney`, `BoxText`, `BoxBroadcastTextID`, `VerifiedBuild`) VALUES (7339, 50, 0, 'I have been sent on behalf of the Sandfury, they have been driven from their home.', 0, 1, 1, 0, 0, 0, 0, NULL, 0, 0);
